with base as (select id, device, browser, started_at, case when country = 'TH' then 1 else 0 end as is_th, coalesce(browser, 'OTHER') as resolved_browser from sessions where browser is not distinct from 'Firefox' and country is not null) select case when is_th >= 73 then 'LARGE' else 'SMALL' end as is_th_tier, sum(case when device = 'mobile' then is_th else 0 end) as mobile_is_th, min(started_at) as first_started_at, count(case when device = 'tablet' then 1 end) as tablet_count, round(avg(is_th), 2) as avg_is_th, count(distinct id) as distinct_ids from base group by 1
